schema:
CREATE TABLE customers (customer_id INTEGER NOT NULL PRIMARY KEY, region TEXT NOT NULL);
CREATE TABLE orders (order_id INTEGER NOT NULL PRIMARY KEY, customer_id INTEGER NOT NULL, total_amount INTEGER NOT NULL, FOREIGN KEY (customer_id) REFERENCES customers (customer_id));
CREATE TABLE shipments (shipment_id INTEGER NOT NULL PRIMARY KEY, customer_id INTEGER NOT NULL, shipping_cost INTEGER NOT NULL, shipped_date DATE NOT NULL, FOREIGN KEY (customer_id) REFERENCES customers (customer_id));
